  float acc[RowsPerWarp][4];
  #pragma unroll
  for (int rp = 0; rp < RowsPerWarp; ++rp) {
    acc[rp][0] = 0.0f; acc[rp][1] = 0.0f; acc[rp][2] = 0.0f; acc[rp][3] = 0.0f;
  }
  const bool vecOk = ((K & 3) == 0) &&
                     ((reinterpret_cast<uintptr_t>(A) & 0xF) == 0) &&
                     ((reinterpret_cast<uintptr_t>(B) & 0xF) == 0);
