          __pipeline_memcpy_async(&sB[buf ^ 1][i], &gBv(cN + i), sizeof(float4));
        __pipeline_commit();
        __pipeline_wait_prior(1);
      } else {
        __pipeline_wait_prior(0);
      }
      __syncthreads();
      #pragma unroll
      for (int rp = 0; rp < RowsPerWarp; ++rp) {
        const int row = m0 + wid + rp * NumWarps;
