            const float4 b2 = sB[buf][i + 64];
            const float4 b3 = sB[buf][i + 96];
            const float4 a0 = __ldcs(aVec + c0 + i);
            const float4 a1 = __ldcs(aVec + c0 + i + 32);
            const float4 a2 = __ldcs(aVec + c0 + i + 64);
            const float4 a3 = __ldcs(aVec + c0 + i + 96);
            acc[rp][0] = fmaf(a0.x, b0.x, fmaf(a0.y, b0.y, fmaf(a0.z, b0.z, fmaf(a0.w, b0.w, acc[rp][0]))));
