  constexpr int ChunkV     = 1024;            // float4 per shared-memory B chunk (16KB)
  const int64_t Mt = (M + RowsPerCTA - 1) / RowsPerCTA;
  dim3 grid((unsigned)Mt, (unsigned)S);
  dim3 block(BlockSize);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  matvec_kernel<BlockSize, RowsPerCTA, ChunkV><<<grid, block, 0, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      (int)M, (int)K, (int)Kc);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ",
              cudaGetErrorString(err));
  return C;
}
